with supplier_totals as (select supplier_id, sort_array(collect_set(category)) as category_list, sum(case when category = 'Home' then 1 else 0 end) as home_count from products where supplier_id in (4, 16, 27, 33) group by supplier_id) select s.id, s.city, st.category_list, st.home_count from suppliers s join supplier_totals st on s.id = st.supplier_id order by s.id desc, st.home_count desc
